% Detlog code generated by detlog2 from examples/splice.pl
% No cuts and no choicepoints: every predicate succeeds exactly once and
% returns its answer packet (rows and out(Text) items) in its last argument.
% Run it with: detlog2 run --det FILE 'p__cp(Args..., Packet)'
%
% predicate_to_packet(c/2, 1 clauses)
% splice_early(a(A), b(B))
% predicate_to_packet(a/1, 1 clauses)
% member_to_member_cp
% predicate_to_packet(b/1, 1 clauses)
% member_to_member_cp
% predicate_to_packet(triple/3, 1 clauses)
% member_to_member_cp
% facts_to_member_cp(p/1, 3 facts)
% predicate_to_packet(q/2, 1 clauses)
% proof accepted: 14 steps, 17 clauses justified

c__cp(A1, A2, Rows) :-
    c__cp_c1([A1, A2], Rows).

c__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [A, B]),
        (   if_commit(
                splice_safe([[A], [B]]),
                (   a__cp(A, P),
                    if_commit(
                        P = [],
                        Env = [],
                        (   b__cp(B, P1),
                            if_commit(
                                P1 = [],
                                Env = [],
                                (   splice([cp(P), cp(P1)], Combos),
                                    splice_extend(Combos, [A, B], [[A], [B]], Env)
                                )
                            )
                        )
                    )
                ),
                (   a__cp(A, Packet),
                    splice_extend(Packet, [A, B], [A], R),
                    c_c1__cp_1(R, Env)
                )
            ),
            splice_extend(Env, [A, B], [A, B], Rows)
        ),
        Rows = []
    ).

c_c1__cp_1([], []).
c_c1__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [A, B]),
            b__cp(B, Packet),
            splice_extend(Packet, [A, B], [B], Out1)
        )
    ),
    c_c1__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).

a__cp(A1, Rows) :-
    a__cp_c1([A1], Rows).

a__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [A]),
        (   member_cp(P, [1, 2]),
            cp_rows(P, PRows),
            splice_extend(PRows, [A], [A], Env),
            splice_extend(Env, [A], [A], Rows)
        ),
        Rows = []
    ).

b__cp(A1, Rows) :-
    b__cp_c1([A1], Rows).

b__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [B]),
        (   member_cp(P, [3, 4]),
            cp_rows(P, PRows),
            splice_extend(PRows, [B], [B], Env),
            splice_extend(Env, [B], [B], Rows)
        ),
        Rows = []
    ).

triple__cp(A1, A2, A3, Rows) :-
    triple__cp_c1([A1, A2, A3], Rows).

triple__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X, Y, Z]),
        (   if_commit(
                X = fixed,
                (   member_cp(P, [1, 2]),
                    cp_rows(P, PRows),
                    splice_extend(PRows, [X, Y, Z], [Y], R),
                    triple_c1__cp_1(R, Env)
                ),
                Env = []
            ),
            splice_extend(Env, [X, Y, Z], [X, Y, Z], Rows)
        ),
        Rows = []
    ).

triple_c1__cp_1([], []).
triple_c1__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [X, Y, Z]),
            if_commit(
                Z = x,
                Out1 = [[X, Y, Z]],
                Out1 = []
            )
        )
    ),
    triple_c1__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).

p__cp(A1, Rows) :-
    member_cp(P, [[1], [2], [3]]),
    cp_filter(P, [A1], Rows).

q__cp(A1, A2, Rows) :-
    q__cp_c1([A1, A2], Rows).

q__cp_c1(Args, Rows) :-
    if_commit(
        copy_term(Args, [X, Y]),
        (   p__cp(X, Packet),
            splice_extend(Packet, [X, Y], [X], R),
            q_c1__cp_1(R, Env),
            splice_extend(Env, [X, Y], [X, Y], Rows)
        ),
        Rows = []
    ).

q_c1__cp_1([], []).
q_c1__cp_1([Row|Rows], Out) :-
    if_commit(
        Row = out(Text),
        Out1 = [out(Text)],
        (   copy_term(Row, [X, Y]),
            if_commit(
                (   Y is X * 10,
                    Y > 10
                ),
                Out1 = [[X, Y]],
                Out1 = []
            )
        )
    ),
    q_c1__cp_1(Rows, Out2),
    rows_concat([Out1, Out2], Out).
